var a=[{title:`L’obiettivo dell’allenamento`,text:`Gli esercizi pliometrici sviluppano la tua capacità di produrre forza rapidamente; restare senza fiato non è il punto. Esempi sono piccoli saltelli pogo, squat jump, saltelli laterali e balzi. Salti più veloci o più alti richiedono più coordinazione e più impatto, quindi il tuo livello di partenza dipende da forza, controllo dell’atterraggio e storia di allenamento.`},{title:`Esercitati in un atterraggio controllato`,text:`Inizia con saltelli bassi e facili e atterra piegando insieme anche, ginocchia e caviglie. Punta a un contatto equilibrato del piede e a un tronco controllato, senza ginocchia bloccate né atterraggi rumorosi e sciatti. Le ginocchia non devono restare perfettamente ferme, ma non dovrebbero perdere il controllo all’improvviso. Fermati se senti dolore o se continui a inciampare.`},{title:`Progredisci una cosa alla volta`,text:`Rendi i salti più difficili gradualmente, per esempio da piccoli saltelli a due piedi a modesti salti verticali prima di provare balzi ripetuti o su una gamba. Box alti, salti dall’alto e salti zavorrati richiedono più abilità e sono pessimi primi passi. Aggiungi altezza, velocità o lavoro su una gamba solo quando le ripetizioni più facili restano affidabili.`},{title:`Conta i buoni contatti`,text:`I contatti del piede, cioè il numero di volte in cui i piedi atterrano, vengono spesso usati per misurare il volume pliometrico della parte bassa del corpo. Da principiante potresti aver bisogno solo di un piccolo numero di contatti controllati, anche se i programmi atletici indicano totali più alti. Riposa abbastanza tra le serie brevi. Un circuito di salti che ti stanca non sviluppa potenza come ripetizioni fresche ed esplosive.`},{title:`Usare TrainUp`,text:`Il piano include esercizi di salto solo quando il tuo Profilo consente di saltare e il rumore che producono, e la tua superficie e le dimensioni del pavimento sono adatte. Conta anche il tuo livello. Se qualcuno di questi non è adatto, allenati con esercizi di forza o di condizionamento a basso impatto. Se un atterraggio fa male, tocca «Sento dolore»: l’esercizio termina subito e resta fuori dai tuoi piani finché non lo riprendi dal Profilo.`}];var o=[{label:`Position stand ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Sintesi ACSM 2026 sull’allenamento di forza`,url:`https://acsm.org/resistance-training-guidelines-update-2026/`},{label:`Libreria di esercizi ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var t={sections:a,sources:o};export{t as default,a as sections,o as sources};